{"path":"/app/airline_analysis.py","content":"from math import lcm
from pathlib import Path


PERIODS = (100, 120, 150)
RESULT_PATH = Path('/app/results.txt')


def longest_no_flight_streak(offsets):
    """Return the longest circular run of no-flight days in one full period."""
    cycle = lcm(*PERIODS)
    flight_days = sorted(
        day
        for day in range(cycle)
        if any((day - offset) % period == 0 for period, offset in zip(PERIODS, offsets))
    )

    longest = 0
    for current_day, next_day in zip(flight_days, flight_days[1:] + [flight_days[0] + cycle]):
        longest = max(longest, next_day - current_day - 1)
    return longest


def solve():
    """Find the greatest guaranteed number of consecutive no-flight days."""
    cycle = lcm(*PERIODS)
    best_guaranteed = cycle

    # A common shift of all departures does not change gap lengths, so fix the
    # first airline's offset at 0 and enumerate only the relative offsets.
    for second_offset in range(PERIODS[1]):
        for third_offset in range(PERIODS[2]):
            longest = longest_no_flight_streak((0, second_offset, third_offset))
            best_guaranteed = min(best_guaranteed, longest)

    return best_guaranteed


def main():
    RESULT_PATH.write_text(f'{solve()}\n', encoding='utf-8')


if __name__ == '__main__':
    main()
"}

